CREATE OR REPLACE FUNCTION public.is_team_member(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ select exists (select 1 from public.user_roles where user_id = _user_id) $$;
REVOKE EXECUTE ON FUNCTION public.is_team_member(uuid) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.is_team_member(uuid) TO authenticated;
ALTER POLICY "members read profiles" ON public.profiles USING (public.is_team_member(auth.uid()));
ALTER POLICY "members read roles" ON public.user_roles USING (public.is_team_member(auth.uid()));
ALTER POLICY "members read" ON public.batches USING (public.is_team_member(auth.uid()));
ALTER POLICY "members insert" ON public.batches WITH CHECK (public.is_team_member(auth.uid()));
ALTER POLICY "members update" ON public.batches USING (public.is_team_member(auth.uid())) WITH CHECK (public.is_team_member(auth.uid()));
